/**
 * Wire types for `GET /v1/ai-provider-connectors` — mirror of the
 * platform's `AiProviderConnector` + nested `AiModel` records.
 *
 * `legacy` on the model distinguishes older connector types; the EDK
 * agent builder prefers non-legacy connectors when creating new agents.
 */
export interface AiModel {
    readonly name?: string;
    readonly model?: string;
    readonly modelType?: string;
    readonly legacy?: boolean;
}
export interface AiProviderConnector {
    readonly id: string;
    readonly clientHandle?: string;
    readonly model?: AiModel;
}
